def classify(test_names):
    counts = {'unit': 0, 'integration': 0, 'e2e': 0}
    for name in test_names:
        if name.startswith('unit_'):
            counts['unit'] += 1
        elif name.startswith('integration_'):
            counts['integration'] += 1
        elif name.startswith('e2e_'):
            counts['e2e'] += 1
    return counts

tests = [
    'unit_add', 'unit_subtract', 'unit_multiply', 'unit_divide',
    'integration_save_user', 'integration_login',
    'e2e_checkout',
]

counts = classify(tests)
total = sum(counts.values())
for level in ('unit', 'integration', 'e2e'):
    pct = counts[level] / total * 100
    print(f'{level}: {counts[level]} tests ({pct:.0f}%)')

if counts['e2e'] > counts['unit']:
    print('Warning: inverted pyramid - too many E2E tests')
else:
    print('Pyramid shape OK')
